__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,"__esModule",{value:!0});const t=r(d[0]),n=(t,n)=>`[${t}](${n})`,o={[t.autoPostsTemplates.GAME_WEEK_SUMMARY]:{name:t.autoPostsTemplates.GAME_WEEK_SUMMARY,attributes:['badCoaching','badSuitcase','goldenDoc','goldenSuarez','goldenVicky','goldenNerfAllPlayers','onFire','punishment'],localization:{[t.languages.FR]:{content:'R\xe9sum\xe9 de la journ\xe9e :\n%badSuitcase%%badCoaching%%punishment%%onFire%%goldenVicky%%goldenSuarez%%goldenDoc%%goldenNerfAllPlayers%'},[t.languages.EN]:{content:'Matchweek summary:\n%badSuitcase%%badCoaching%%punishment%%onFire%%goldenVicky%%goldenSuarez%%goldenDoc%%goldenNerfAllPlayers%'},[t.languages.ES]:{content:'Resumen de vuestra jornada:\n%badSuitcase%%badCoaching%%punishment%%onFire%%goldenVicky%%goldenSuarez%%goldenDoc%%goldenNerfAllPlayers%'}}},[t.autoPostsTemplates.POSTPONED_MATCH_SUMMARY]:{name:t.autoPostsTemplates.POSTPONED_MATCH_SUMMARY,attributes:['gameWeek','teams','matchesDetails'],localization:{[t.languages.FR]:{content:'\ud83d\ude31 Coup de chaud, un match report\xe9 de %gameWeek% a eu lieu hier, les notes et buts des joueurs de %teams% ont \xe9t\xe9 mis \xe0 jour :\n\n%matchesDetails%'},[t.languages.EN]:{content:'Ouch, a postponed game was played for %gameWeek% : %teams%. Results have been updated:\n\n%matchesDetails%'},[t.languages.ES]:{content:'Ayer se jugaba un partido pospuesto de la %gameWeek% : %teams%. Nuevos resultados:\n\n%matchesDetails%'}}},[t.autoPostsTemplates.POSTPONED_MATCH_SUMMARY_PLURAL]:{name:t.autoPostsTemplates.POSTPONED_MATCH_SUMMARY_PLURAL,attributes:['matchesQuantity','gameWeek','teams','matchesDetails'],localization:{[t.languages.FR]:{content:'\ud83d\ude31 Coup de chaud, %matchesQuantity% matchs report\xe9s de %gameWeek% ont eu lieu hier, les notes et buts des joueurs des \xe9quipes concern\xe9es (%teams%) ont \xe9t\xe9 mis \xe0 jour :\n\n%matchesDetails%'},[t.languages.EN]:{content:'Ouch, %matchesQuantity% postponed games (%teams%) were played for %gameWeek%. Results have been updated:\n\n%matchesDetails%'},[t.languages.ES]:{content:'Ayer se jugaban partidos pospuestos (%teams%) de la %gameWeek%. Nuevos resultados :\n\n%matchesDetails%'}}},[t.autoPostsTemplates.UPGRADE_EXPERT_MODE]:{name:t.autoPostsTemplates.UPGRADE_EXPERT_MODE,attributes:['midSeasonBudget','leagueId','divisionId'],localization:{[t.languages.FR]:{content:`Dernier jour pour ${n('activer','/app/shopInformationProductBonus/expert')} le Mode Expert et r\xe9cup\xe9rer %midSeasonBudget%M\u20ac de budget mi-saison.\nTu pourras t'acheter de ${n('nouveaux joueurs','/app/league/%leagueId%/%divisionId%/trading')} et vendre tes canards boiteux.`},[t.languages.EN]:{content:`You still have a few days left to ${n('activate','/app/shopInformationProductBonus/expert')} the expert mode. Receive a \xa3%midSeasonBudget%M bonus to buy ${n('new players','/app/league/%leagueId%/%divisionId%/trading')} and sell your initial transfer window mistakes.`},[t.languages.ES]:{content:`Tienes a\xfan un par de d\xedas para ${n('activar','/app/shopInformationProductBonus/expert')} el Modo Experto. Recibe un bonus de %midSeasonBudget%M para comprar ${n('jugadores','/app/league/%leagueId%/%divisionId%/trading')} a mitad de temporada.`}}},[t.autoPostsTemplates.LEAGUE_CREATION]:{name:t.autoPostsTemplates.LEAGUE_CREATION,attributes:['adminFirstName','userId'],localization:{[t.languages.FR]:{content:`Merci ${n('%adminFirstName%','/app/profile/%userId%')} d'avoir cr\xe9\xe9 la ligue \ud83e\udd1d\nLe dernier paiera son ap\xe9ro ?`},[t.languages.EN]:{content:`Shoutout to ${n('%adminFirstName%','/app/profile/%userId%')} who create the league \ud83e\udd1d\nDid you already choose a prize for the winner?`},[t.languages.ES]:{content:`Puedes empezar dando las gracias a ${n('%adminFirstName%','/app/profile/%userId%')} por esta liga \ud83e\udd1d\n\xbfHas elegido el premio para el ganador?`}}},[t.autoPostsTemplates.LEAGUE_CREATION_IMAGE]:{name:t.autoPostsTemplates.LEAGUE_CREATION_IMAGE,attributes:['imageBaseUrl'],localization:{[t.languages.FR]:{imageUrl:'%imageBaseUrl%image.mpg/convention_FR.jpg'},[t.languages.EN]:{imageUrl:'%imageBaseUrl%image.mpg/convention_EN.jpg'},[t.languages.ES]:{imageUrl:'%imageBaseUrl%image.mpg/convention_ES.jpg'}}},[t.autoPostsTemplates.PUBLIC_LEAGUE_CREATION]:{name:t.autoPostsTemplates.PUBLIC_LEAGUE_CREATION,attributes:[],localization:{[t.languages.FR]:{content:"Salut, tu peux te pr\xe9senter rapide ? Club de coeur, expertise foot, qualit\xe9 de blague... On n'est pas sur Tinder, c'est juste pour savoir qui est derri\xe8re ce clavier. Et aussi dire avec quels engagements tu es en phase."},[t.languages.EN]:{content:'Hello, can you introduce yourself? Favourite Team, football expertise, level of entertainer... We are not on Tinder, just to know who is hidding behing the screen. And also what is your level of involvement on this crazy game.'},[t.languages.ES]:{content:'Hola, \xbfpuedes presentarte r\xe1pido? Heart club, experiencia futbol\xedstica, calidad de broma ... No estamos en Tinder, es solo para saber qui\xe9n est\xe1 detr\xe1s de este teclado. Y tambi\xe9n di con qu\xe9 compromisos est\xe1s en fase.'}}},[t.autoPostsTemplates.MULTI_DIVISION_CREATION]:{name:t.autoPostsTemplates.MULTI_DIVISION_CREATION,attributes:[],localization:{[t.languages.FR]:{content:'Oulala ya du beau monde par ici. Chacun peut mettre quelques lignes pour se pr\xe9senter ? Expertise foot, niveau de dr\xf4lerie et de mauvaise foi... l\xe2chez-vous !'},[t.languages.EN]:{content:"There are beautiful people around here. Can everyone put a few lines to introduce themselves? Football expertise, level of fun and bad faith ... Let's go"},[t.languages.ES]:{content:'Son gente guapa por aqu\xed. \xbfTodos pueden poner algunas l\xedneas para presentarse? Experiencia futbol\xedstica, nivel de diversi\xf3n y mala fe ... Su\xe9ltalo'}}},[t.autoPostsTemplates.TOURNAMENT_CREATION]:{name:t.autoPostsTemplates.TOURNAMENT_CREATION,attributes:['adminFirstName','userId'],localization:{[t.languages.FR]:{content:`\ud83d\ude4c Bienvenue dans ce tournoi cr\xe9\xe9 par ${n('%adminFirstName%','/app/profile/%userId%')} que l'on remercie.\n\ud83d\udd01 Change tes joueurs autant que tu veux jusqu'\xe0 1h avant le 1er tour, car apr\xe8s, les changements de ton effectif seront volontairement limit\xe9s pendant le tournoi.\n\ud83d\udcd6 Et jette un oeil aux ${n('r\xe8gles','/app/menu/rules/tournament')} pour \xeatre au taquet.`},[t.languages.EN]:{content:`\ud83d\ude4c Welcome to this tournament created by ${n('%adminFirstName%','/app/profile/%userId%')} who we thank.\n\ud83d\udd01 Change your players as much as you want until 1 hour before the 1st round, because after that, changes in your squad will be voluntarily limited during the tournament.\n\ud83d\udcd6 And take a look at the ${n('rules','/app/menu/rules/tournament')} to be on top of things.`},[t.languages.ES]:{content:`\ud83d\ude4c Bienvenido a este torneo creado por ${n('%adminFirstName%','/app/profile/%userId%')} a quien agradecemos\n\ud83d\udd01 Cambia tus jugadores tanto como quieras hasta 1 hora antes de la 1\xaa ronda, porque despu\xe9s de eso, los cambios en tu plantilla se limitar\xe1n voluntariamente durante el torneo.\n\ud83d\udcd6 Y eche un vistazo a las ${n('reglas','/app/menu/rules/tournament')} para estar al tanto de las cosas.`}}},[t.autoPostsTemplates.TOURNAMENT_CREATION_IMAGE]:{name:t.autoPostsTemplates.TOURNAMENT_CREATION_IMAGE,attributes:['imageBaseUrl'],localization:{[t.languages.FR]:{imageUrl:'%imageBaseUrl%image.mpg/tournament_welcome_image_FR.jpg'},[t.languages.EN]:{imageUrl:'%imageBaseUrl%image.mpg/tournament_welcome_image_EN.jpg'},[t.languages.ES]:{imageUrl:'%imageBaseUrl%image.mpg/tournament_welcome_image_ES.jpg'}}},[t.autoPostsTemplates.USER_REPLACED_BY_USER]:{name:t.autoPostsTemplates.USER_REPLACED_BY_USER,attributes:['teamName','userId','userUsername'],localization:{[t.languages.FR]:{content:`Y'a du changement par ici, le nouveau coach de ${n('%teamName%','/app/profile/%userId%')} est : ${n('%userUsername%','/app/profile/%userId%')}`},[t.languages.EN]:{content:`The new coach of ${n('%teamName%','/app/profile/%userId%')} is now : ${n('%userUsername%','/app/profile/%userId%')}`},[t.languages.ES]:{content:`El nuevo entrenador de ${n('%teamName%','/app/profile/%userId%')} es : ${n('%userUsername%','/app/profile/%userId%')}`}}},[t.autoPostsTemplates.USER_LEAVE_LEAGUE]:{name:t.autoPostsTemplates.USER_LEAVE_LEAGUE,attributes:['userFirstName','userId'],localization:{[t.languages.FR]:{content:`\ud83d\ude4b\u200d\u2640\ufe0f Ce n'est qu'un au revoir : ${n('%userFirstName%','/app/profile/%userId%')} vient de quitter la ligue. Son \xe9quipe, son staff et ses supporters lui cherchent un rempla\xe7ant.\nRappel : seul le cr\xe9ateur de votre ligue peut faire le changement depuis sa page R\xe9glages`},[t.languages.EN]:{content:`\ud83d\ude4b\u200d\u2640\ufe0f It's only goodbye for now: ${n('%userFirstName%','/app/profile/%userId%')} just left the league. His squad, staff, stadium and fans are now waiting for their new manager.\nReminder: only your league administrator can switch players in the settings tab.`},[t.languages.ES]:{content:`Solo es un hasta luego: ${n('%userFirstName%','/app/profile/%userId%')} acaba de abandonar la liga. Su equipo, el personal, el estadio y los aficionados estan esperando a su nuevo jefe.\nRecordatorio: el administrador es el unico que puede cambiar jugadores en la pesta\xf1a configuraci\xf3n de la liga.`}}},[t.autoPostsTemplates.ADMIN_REPLACED]:{name:t.autoPostsTemplates.ADMIN_REPLACED,attributes:['oldAdminFirstName','oldAdminId','newAdminFirstName','newAdminId'],localization:{[t.languages.FR]:{content:`\ud83e\udd2a Grosse annonce : ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} n'est plus admin de la ligue... c'est d\xe9sormais ${n('%newAdminFirstName%','/app/profile/%newAdminId%')} qui s'en charge. Pression.`},[t.languages.EN]:{content:`Warning : ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} has deliberatly decided to quit the administrator position in the league. Shame on him.\n${n('%newAdminFirstName%','/app/profile/%newAdminId%')} is glad to replace him. Will he live up to your expectations though?`},[t.languages.ES]:{content:`Cuidado: ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} ha tomado la decisi\xf3n de abandonar el desarllo de administrator en la liga. Que pena...\n${n('%newAdminFirstName%','/app/profile/%newAdminId%')} se complace en reemplazarlo. \xbfEstar\xe1 a la altura de sus expectativas?`}}},[t.autoPostsTemplates.ADMIN_LEAVE_LEAGUE]:{name:t.autoPostsTemplates.ADMIN_LEAVE_LEAGUE,attributes:['oldAdminFirstName','oldAdminId','newAdminFirstName','newAdminId'],localization:{[t.languages.FR]:{content:`\ud83d\ude2f Coup de th\xe9\xe2tre : ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} a solennellement d\xe9cid\xe9 de quitter la ligue... et sera remplac\xe9 par ${n('%newAdminFirstName%','/app/profile/%newAdminId%')}. C'est mieux non ?`},[t.languages.EN]:{content:`Warning : ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} has deliberatly decided to quit the league. Shame on him.\n${n('%newAdminFirstName%','/app/profile/%newAdminId%')} is glad to replace him. Will he live up to your expectations though?`},[t.languages.ES]:{content:`Cuidado: ${n('%oldAdminFirstName%','/app/profile/%oldAdminId%')} ha tomado la decisi\xf3n de abandonar la liga. Que pena...\n${n('%newAdminFirstName%','/app/profile/%newAdminId%')} se complace en reemplazarlo. \xbfEstar\xe1 a la altura de sus expectativas?`}}},[t.autoPostsTemplates.MERCATO_CLOSED]:{name:t.autoPostsTemplates.MERCATO_CLOSED,attributes:['higherBids','bidsLosers','biggestTeamsSquads','lowerHigherBids'],localization:{[t.languages.FR]:{content:"%higherBids%%bidsLosers%%biggestTeamsSquads%%lowerHigherBids%"},[t.languages.EN]:{content:"%higherBids%%bidsLosers%%biggestTeamsSquads%%lowerHigherBids%"},[t.languages.ES]:{content:"%higherBids%%bidsLosers%%biggestTeamsSquads%%lowerHigherBids%"}}},[t.autoPostsTemplates.MID_SEASON_EXPERT]:{name:t.autoPostsTemplates.MID_SEASON_EXPERT,attributes:['leagueId','divisionId','midSeasonBudget'],localization:{[t.languages.FR]:{content:`${n('Fais tes ench\xe8res avant ce soir','/app/league/%leagueId%/%divisionId%/trading')} !\nUn tour de mercato vient de s'ouvrir gr\xe2ce \xe0 votre mode Expert et on vient de te cr\xe9diter de %midSeasonBudget%M\u20ac tout frais.`},[t.languages.EN]:{content:`For those who miserably failed during the first transfer window, there is still hope. We are giving you a second chance to adjust your squad with \xa3%midSeasonBudget%M. Do not wait too much this time and ${n('enter your bids before tonight!','/app/league/%leagueId%/%divisionId%/trading')}`},[t.languages.ES]:{content:`Para todos aquellos que han sido muy paquetes en la primera ronda de pujas, todav\xeda hay esperanza. Os damos una segunda oportunidad para cambiar los equipos con un bonus de \u20ac%midSeasonBudget%M. No esper\xe9is mucho y ${n('haced las pujas antes de esta noche','/app/league/%leagueId%/%divisionId%/trading')}.`}}},[t.autoPostsTemplates.DIVISION_AWARDS_VOTE]:{name:t.autoPostsTemplates.DIVISION_AWARDS_VOTE,attributes:['leagueId','divisionId'],localization:{[t.languages.FR]:{content:`Viens voter pour attribuer les Palmes du seum, du fun... de votre ligue lors de la c\xe9r\xe9monie des Rotald'Or\n\n${n('Je vote','/app/winner/%leagueId%/%divisionId%/vote')}`},[t.languages.EN]:{content:`Vote for the luckiest, the funiest or the more vicious of the league for the Rotald'Or ceremony\n\n${n('I vote','/app/winner/%leagueId%/%divisionId%/vote')}`},[t.languages.ES]:{content:`Elige el m\xe1s afortunado, vicioso o matem\xe1tico\u2026 de tu liga para la ceremonia de los Rotald'Or\n\n${n('Voy a votar','/app/winner/%leagueId%/%divisionId%/vote')}`}}},[t.autoPostsTemplates.DIVISION_AWARDS_RESULTS]:{name:t.autoPostsTemplates.DIVISION_AWARDS_RESULTS,attributes:['leagueId','divisionId'],localization:{[t.languages.FR]:{content:`Alors qui a d\xe9croch\xe9 les Palmes du seum, du fun, du vice, de la ch**te et de Pythagore ?\n\n${n("D\xe9couvrir les Rotald'Or",'/app/winner/%leagueId%/%divisionId%/rotaldor')}`},[t.languages.EN]:{content:`So who won the sore loser, fun or vice awards ?\n\n${n("Discover the Rotald'Or",'/app/winner/%leagueId%/%divisionId%/rotaldor')}`},[t.languages.ES]:{content:`\xbfQui\xe9n a ganado las palmas del payaso, del peor perdedor o del vicio?\n\n${n("Descubre los Rotald'Or",'/app/winner/%leagueId%/%divisionId%/rotaldor')}`}}},[t.autoPostsTemplates.HOTFIX_PL_GW_29_CANCELED]:{name:t.autoPostsTemplates.HOTFIX_PL_GW_29_CANCELED,attributes:[],localization:{[t.languages.FR]:{content:'Hello ! \xc9tant donn\xe9 tous les matchs report\xe9s et conform\xe9ment aux r\xe8gles on a d\xfb annuler la journ\xe9e 29. Le dernier tour a donc \xe9t\xe9 annul\xe9 et sera rejou\xe9 \xe0 la prochaine journ\xe9e. Bon chance !',imageUrl:'https://s3.eu-west-1.amazonaws.com/image.mpg/9a695f0f0056113dcc8dc4d2829417c6.jpeg'},[t.languages.EN]:{content:'Hello! Considering the amount of postponed matches and in accordance with the rules, we had to cancel the game week 29. The last round has been canceled and will be replayed on the next game week. Good luck!',imageUrl:'https://s3.eu-west-1.amazonaws.com/image.mpg/9a695f0f0056113dcc8dc4d2829417c6.jpeg'},[t.languages.ES]:{content:'\xa1Hola! Dado todos los partidos aplazados y conforme a las reglas, tuvimos que cancelar la Semana de Juego 29. Por lo tanto, la \xfaltima ronda ha sido cancelada y se jugar\xe1 de nuevo en la pr\xf3xima semana de juego. \xa1Buena suerte!',imageUrl:'https://s3.eu-west-1.amazonaws.com/image.mpg/9a695f0f0056113dcc8dc4d2829417c6.jpeg'}}}};Object.keys(o).forEach(t=>{Object.keys(o[t].localization).forEach(n=>{const s=o[t].localization[n];if('content'in s){const l=s.content.match(/%([^%]+)%/g);l&&l.forEach(s=>{const l=s.slice(1,-1);o[t].attributes.includes(l)||console.error(`Attribute "${l}" used in template "${t}" for locale "${n}" is not declared in attributes array`)})}})}),e.default=o},2193,[1966]);
